const body = $input.first().json.body ?? {};
const question = String(body.question ?? '').trim();
const askedBy = String(body.asked_by ?? '').slice(0, 254);
const supplied = Array.isArray(body.schemas) ? body.schemas : [];
const maxRows = Math.min(Math.max(Number(body.max_rows) || 250, 1), 5000);
const ident = /^[a-z][a-z0-9_]{0,62}$/;

// Columns holding a comma-separated list. Send multi_value:true on a column in
// the request payload to add one without editing this node.
const MULTI_VALUE = new Set(['sectors_norm', 'categories', 'region_tags_raw']);
// Columns that hold numbers even when the DDL says TEXT. Drives CAST(...) so
// that founded > 2015 and ORDER BY founded DESC compare numerically.
const NUMERIC_HINT = new Set(['founded', 'funding_total_usd', 'funding_rounds',
  'year', 'employees', 'revenue', 'amount', 'headcount', 'age', 'rank', 'score']);
const NUMERIC_TYPE = /int|decimal|numeric|float|double|real|year|bit/i;

if (!question) return [{json:{valid:false,statusCode:400,error:'Missing question'}}];
if (question.length > 2000) return [{json:{valid:false,statusCode:400,error:'Question is too long (maximum 2,000 characters)'}}];
if (!supplied.length) return [{json:{valid:false,statusCode:422,error:'No searchable datasets are available'}}];

const schemas = supplied.filter(s => s && ident.test(String(s.table ?? '')) && Array.isArray(s.columns)).map(s => ({
  table: String(s.table),
  label: String(s.label ?? s.table).slice(0,150),
  description: String(s.description ?? '').slice(0,500),
  row_count: Math.max(0, Number(s.row_count ?? 0)),
  columns: s.columns.filter(c => c && ident.test(String(c.name ?? ''))).map(c => {
    const name = String(c.name);
    const type = String(c.type ?? 'TEXT').slice(0,100);
    return {
      name,
      type,
      label: String(c.label ?? name).slice(0,100),
      description: String(c.description ?? '').slice(0,300),
      multi: c.multi_value === true || MULTI_VALUE.has(name),
      numeric: NUMERIC_TYPE.test(type) || c.numeric === true || NUMERIC_HINT.has(name),
      declared_numeric: NUMERIC_TYPE.test(type),
      values: Array.isArray(c.values) ? c.values.slice(0,100).map(v => String(v).slice(0,200)) : []
    };
  })
})).filter(s => s.columns.length);

if (!schemas.length) return [{json:{valid:false,statusCode:422,error:'No valid searchable schemas were supplied'}}];

// Datasets with an identical column set are shards of one logical dataset.
// Only one can be queried, so tell the planner which shard is biggest.
const signature = s => s.columns.map(c => c.name).sort().join(',');
const groups = new Map();
for (const s of schemas) {
  const k = signature(s);
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(s);
}
for (const members of groups.values()) {
  const biggest = members.reduce((a,b) => b.row_count > a.row_count ? b : a);
  for (const s of members) {
    s.shard_siblings = members.filter(m => m.table !== s.table).map(m => m.table);
    s.preferred_shard = biggest.table;
  }
}

const schemaText = schemas.map(s => {
  const cols = s.columns.map(c => {
    let line = `- ${c.name} (${c.type})`;
    if (c.label !== c.name) line += `; label: ${c.label}`;
    if (c.description) line += `; ${c.description}`;
    if (c.multi) line += '; MULTI-VALUE comma-separated list';
    if (c.numeric) line += '; numeric';
    line += c.values.length ? `; known values: ${c.values.join(' | ')}` : '; no known value list, treat as free text';
    return line;
  }).join('\n');
  const multiCols = s.columns.filter(c => c.multi).map(c => c.name);
  let rules = '';
  if (multiCols.length) rules += `\nMULTI-VALUE COLUMNS: ${multiCols.join(', ')}`;
  if (s.shard_siblings.length) {
    rules += `\nSHARD: same columns as ${s.shard_siblings.join(', ')}. Only one may be queried;`;
    rules += s.preferred_shard === s.table ? ' this is the largest shard, prefer it.' : ` prefer ${s.preferred_shard} (largest).`;
  }
  if (s.table === 'leads') rules += '\nSPECIAL RULES FOR leads:\n- primary_sector is only the main trade.\n- has_email stores Yes or No as strings.\n- phone_type normally stores mobile, fixed line, voip, or other.\n- contact_person may contain multiple people in one field.\n- Empty values may be either NULL or an empty string.';
  return `TABLE: ${s.table}\nDISPLAY NAME: ${s.label}\nDESCRIPTION: ${s.description || 'No description provided'}\nAPPROXIMATE ROWS: ${s.row_count}\nCOLUMNS:\n${cols}${rules}`;
}).join('\n\n');

return [{json:{valid:true,question,asked_by:askedBy,max_rows:maxRows,schemas,schema_text:schemaText}}];

const source = $('Prepare Dynamic Schema').first().json;
const item = $input.first().json;
const raw = item.text ?? item.output ?? item.message?.content ?? item.choices?.[0]?.message?.content ?? '';
const notes = [];

// --- parse: tolerate code fences and prose wrapped around the JSON object
let plan;
try {
  let s = String(raw).trim();
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) s = fenced[1].trim();
  if (!s.startsWith('{')) {
    const a = s.indexOf('{'), b = s.lastIndexOf('}');
    if (a !== -1 && b > a) s = s.slice(a, b + 1);
  }
  plan = JSON.parse(s);
} catch { return [{json:{valid:false,statusCode:502,error:'The AI returned invalid JSON'}}]; }
if (!plan || typeof plan !== 'object') return [{json:{valid:false,statusCode:502,error:'The AI returned invalid JSON'}}];
if (plan.answerable === false) return [{json:{valid:false,no_query:true,statusCode:422,error:String(plan.explanation || 'This question cannot be answered from the searchable datasets.')}}];

const norm = v => String(v ?? '').trim().toLowerCase();

// --- table: accept the table name or the display label
const schema = source.schemas.find(s => norm(s.table) === norm(plan.table))
            ?? source.schemas.find(s => norm(s.label) === norm(plan.table));
if (!schema) return [{json:{valid:false,statusCode:422,error:'The AI selected an unavailable dataset'}}];

// --- columns: accept the column name or its display label, case-insensitively
const byKey = new Map();
for (const c of schema.columns) {
  byKey.set(norm(c.name), c.name);
  if (!byKey.has(norm(c.label))) byKey.set(norm(c.label), c.name);
}
const meta = new Map(schema.columns.map(c => [c.name, c]));
const resolve = v => byKey.get(norm(v)) ?? null;

const intents = new Set(['list','count','aggregate']);
const operators = new Set(['equals','not_equals','contains','contains_any','starts_with','ends_with','is_empty','is_not_empty','greater_than','greater_or_equal','less_than','less_or_equal','between','in']);
const NUMERIC_OPS = new Set(['greater_than','greater_or_equal','less_than','less_or_equal','between']);
if (!intents.has(plan.intent)) return [{json:{valid:false,statusCode:422,error:'The AI selected an invalid query intent'}}];

// --- select columns
const columns = [];
for (const c of (Array.isArray(plan.columns) ? plan.columns : [])) {
  const r = resolve(c);
  if (!r) { notes.push(`Ignored unknown output column ${c}`); continue; }
  if (!columns.includes(r)) columns.push(r);
}

// --- group_by: a bad grouping changes the meaning of the answer, so reject it
const groupBy = [];
for (const g of (Array.isArray(plan.group_by) ? plan.group_by : [])) {
  const r = resolve(g);
  if (!r) return [{json:{valid:false,statusCode:422,error:`Unknown column selected: ${g}`}}];
  if (!groupBy.includes(r)) groupBy.push(r);
}
if (plan.intent === 'aggregate' && !groupBy.length) return [{json:{valid:false,statusCode:422,error:'An aggregate query requires group_by'}}];
if (groupBy.length > 3) return [{json:{valid:false,statusCode:422,error:'At most 3 group_by columns are supported'}}];

// --- order_by: cosmetic, so normalise shapes and drop what cannot be sorted
const orderBy = [];
for (const o of (Array.isArray(plan.order_by) ? plan.order_by : [])) {
  let col, dir;
  if (typeof o === 'string') { col = o; dir = 'asc'; }
  else if (o && typeof o === 'object' && o.column) { col = o.column; dir = String(o.direction ?? 'asc').toLowerCase(); }
  else if (o && typeof o === 'object') { const k = Object.keys(o)[0]; if (!k) continue; col = k; dir = String(o[k] ?? 'asc').toLowerCase(); }
  else continue;
  if (!['asc','desc'].includes(dir)) dir = 'asc';
  const r = resolve(col);
  if (!r) { notes.push(`Ignored sort on ${col}, which is not a column of ${schema.table}`); continue; }
  if (!orderBy.some(x => x.column === r)) orderBy.push({ column: r, direction: dir });
}

// --- filters
const filters = (Array.isArray(plan.filters) ? plan.filters : []).slice(0, 8);
const clean = [];
for (const f of filters) {
  if (!f || typeof f !== 'object') continue;
  const col = resolve(f.column);
  if (!col) return [{json:{valid:false,statusCode:422,error:`Unknown filter column: ${f.column}`}}];
  const op = String(f.operator ?? '').toLowerCase();
  if (!operators.has(op)) return [{json:{valid:false,statusCode:422,error:`Invalid filter operator: ${op || f.operator}`}}];
  let value = f.value;

  if (op === 'between') {
    if (!Array.isArray(value) || value.length !== 2) return [{json:{valid:false,statusCode:422,error:'Between requires exactly two values'}}];
  } else if (op === 'in' || op === 'contains_any') {
    if (!Array.isArray(value)) value = [value];
    value = value.filter(v => v !== null && v !== undefined && String(v).trim() !== '');
    if (!value.length || value.length > 50) return [{json:{valid:false,statusCode:422,error:`${op} requires an array of 1-50 values`}}];
  } else if (op !== 'is_empty' && op !== 'is_not_empty') {
    if (value === null || value === undefined || String(value).trim() === '') { notes.push(`Dropped empty filter on ${col}`); continue; }
  }
  if (NUMERIC_OPS.has(op) && !meta.get(col).numeric) {
    notes.push(`Dropped ${op} on ${col}, which is not numeric`);
    continue;
  }
  clean.push({ column: col, operator: op, value });
}

// --- SQL
const qi = n => '`' + n + '`';
const esc = v => {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  if (typeof v === 'boolean') return v ? '1' : '0';
  return "'" + String(v).replace(/\\/g,'\\\\').replace(/'/g,"''").replace(/\u0000/g,'') + "'";
};
const like = v => String(v).replace(/[\\%_]/g, '\\$&');
const num = v => {
  const n = Number(String(v).replace(/[,\s$]/g, ''));
  return Number.isFinite(n) ? String(n) : null;
};
// A numeric column declared TEXT sorts and compares as a string ("999" > "2020"),
// so cast it. Columns already declared INT/BIGINT are used as-is.
const numExpr = n => meta.get(n).declared_numeric ? qi(n) : `CAST(NULLIF(${qi(n)}, '') AS SIGNED)`;

const where = [];
for (const f of clean) {
  const c = qi(f.column);
  switch (f.operator) {
    case 'equals': where.push(`${c} = ${esc(f.value)}`); break;
    case 'not_equals': where.push(`${c} <> ${esc(f.value)}`); break;
    case 'contains': where.push(`LOWER(${c}) LIKE LOWER(${esc('%' + like(f.value) + '%')})`); break;
    case 'starts_with': where.push(`LOWER(${c}) LIKE LOWER(${esc(like(f.value) + '%')})`); break;
    case 'ends_with': where.push(`LOWER(${c}) LIKE LOWER(${esc('%' + like(f.value))})`); break;
    case 'is_empty': where.push(`(${c} IS NULL OR ${c} = '')`); break;
    case 'is_not_empty': where.push(`(${c} IS NOT NULL AND ${c} <> '')`); break;
    case 'in': where.push(`${c} IN (${f.value.map(esc).join(', ')})`); break;
    case 'greater_than': case 'greater_or_equal': case 'less_than': case 'less_or_equal': {
      const n = num(f.value);
      if (n === null) { notes.push(`Dropped ${f.operator} on ${f.column}, value was not a number`); break; }
      const sym = {greater_than:'>',greater_or_equal:'>=',less_than:'<',less_or_equal:'<='}[f.operator];
      where.push(`${numExpr(f.column)} ${sym} ${n}`);
      break;
    }
    case 'between': {
      const lo = num(f.value[0]), hi = num(f.value[1]);
      if (lo === null || hi === null) { notes.push(`Dropped between on ${f.column}, values were not numbers`); break; }
      where.push(`${numExpr(f.column)} BETWEEN ${Math.min(lo,hi)} AND ${Math.max(lo,hi)}`);
      break;
    }
    case 'contains_any': {
      if (meta.get(f.column).multi) {
        // FIND_IN_SET needs strict "a,b,c" with no padding, but real values look
        // like "Travel, Tourism". Normalise both sides and match on delimiters.
        const listExpr = `CONCAT(',', REPLACE(LOWER(${c}), ' ', ''), ',')`;
        where.push('(' + f.value.map(v => `${listExpr} LIKE ${esc('%,' + like(String(v).toLowerCase().replace(/ /g,'')) + ',%')}`).join(' OR ') + ')');
      } else {
        // On an ordinary text column, OR of substring matches. This is what lets
        // one filter cover UK / United Kingdom / England.
        where.push('(' + f.value.map(v => `LOWER(${c}) LIKE LOWER(${esc('%' + like(v) + '%')})`).join(' OR ') + ')');
      }
      break;
    }
  }
}

let sql, outputColumns;
if (plan.intent === 'count') {
  outputColumns = ['total'];
  sql = `SELECT COUNT(*) AS total FROM ${qi(schema.table)}`;
} else if (plan.intent === 'aggregate') {
  outputColumns = [...groupBy,'total'];
  sql = `SELECT ${groupBy.map(qi).join(', ')}, COUNT(*) AS total FROM ${qi(schema.table)}`;
} else {
  outputColumns = columns.length ? columns.slice(0,12) : schema.columns.slice(0,6).map(c => c.name);
  // _row_id rides along outside outputColumns (which drives the visible
  // column list) so the lead site can offer its "flag this lead" control
  // on AI search results the same way it already does on the dataset
  // browser, without the AI ever seeing or choosing this column itself.
  sql = `SELECT ${['_row_id', ...outputColumns].map(qi).join(', ')} FROM ${qi(schema.table)}`;
}
if (where.length) sql += ' WHERE ' + where.join(' AND ');
if (plan.intent === 'aggregate') {
  sql += ' GROUP BY ' + groupBy.map(qi).join(', ') + ' ORDER BY total DESC LIMIT 100';
} else if (plan.intent === 'list') {
  const sortable = orderBy.filter(o => outputColumns.includes(o.column));
  for (const o of orderBy) if (!sortable.includes(o)) notes.push(`Ignored sort on ${o.column}, which is not a selected column`);
  if (sortable.length) sql += ' ORDER BY ' + sortable.map(o => `${meta.get(o.column).numeric ? numExpr(o.column) : qi(o.column)} ${o.direction.toUpperCase()}`).join(', ');
  const cap = Number(source.max_rows) || 5000;
  sql += ` LIMIT ${Math.min(Math.max(Number(plan.limit) || cap, 1), cap)}`;
}
if (schema.shard_siblings?.length) notes.push(`Searched ${schema.table} only; ${schema.shard_siblings.length} more dataset(s) share these columns.`);

return [{json:{valid:true,sql,question:source.question,asked_by:source.asked_by,dataset:schema.table,dataset_label:schema.label,intent:plan.intent,columns:outputColumns,filters_applied:clean.length,notes,shard_siblings:schema.shard_siblings ?? [],explanation:String(plan.explanation || ''),confidence:['high','medium','low'].includes(plan.confidence) ? plan.confidence : 'low'}}];

const plan = $('Validate Plan and Build SQL').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && !r.error);
return [{json:{success:true,question:plan.question,sql:plan.sql,explanation:plan.explanation,confidence:plan.confidence,intent:plan.intent,dataset:plan.dataset,dataset_label:plan.dataset_label,notes:plan.notes ?? [],shard_siblings:plan.shard_siblings ?? [],filters_applied:plan.filters_applied ?? 0,row_count:rows.length,found:rows.length > 0,message:rows.length ? null : 'No records matched that search.',data:rows}}];

const incoming = $input.first().json;
const detail = incoming.error?.message ?? incoming.message ?? incoming.error ?? 'Database query failed';
return [{json:{success:false,error:'The database query failed.',detail:String(detail).slice(0,500)}}];
